  p.fill('#companion-name','Willow');p.click('[data-action="adv-rename"]');p.click('[data-action="adv-mode"][data-id="stay"]');p.click('#close-panel');before=p.evaluate('Realm.diagnostics.adventure.companion');walk(-6,2);advance(1,True)
  after=p.evaluate('Realm.diagnostics.adventure.companion');check('Stay keeps fox in place',before['x']==after['x'] and before['z']==after['z'])
  panel();p.click('[data-action="adv-mode"][data-id="follow"]');p.click('#close-panel');advance(2);check('Follow is accepted',p.evaluate('Realm.state.adventure.companion.mode')=='follow')
  fight('briar-2');walk(0,-3);p.keyboard.press('e');check('Second cache awarded once',p.evaluate('Realm.state.adventure.coins')==7)
  walk(2,-4);click_ground(4,-4);advance(2,True);check('Second barrier excavates via world click',p.evaluate('Realm.state.adventure.dug.includes("2,-2")'))
  fight('sentinel');walk(8,-3);p.click('#interact');panel();p.click('[data-action="adv-equip"][data-id="guard_vest"]');check('Armor changes defense',p.evaluate('Realm.diagnostics.adventure.stats.defense')==4);p.click('#close-panel')
  walk(8,-5.7);advance(.3,True);p.evaluate('Realm.test.view({overview:false,half:12,center:[8,2,-6]});Realm.test.render()');p.screenshot(path=str(OUT/'06-guardian-approach.png'),timeout=30000)
  fight('hart');walk(8,-10);p.click('#interact');check('Guardian defeat enables relic collection',p.evaluate('Realm.state.adventure.relic'))
  p.click('#interact');check('Guardian cache adds ore and sunmarks',p.evaluate('Realm.state.adventure.coins')==25)
  p.evaluate('Realm.test.quality("balanced");Realm.test.view({overview:true});Realm.test.render()');p.screenshot(path=str(OUT/'06-cleared-underways.png'),timeout=30000)
  walk(0,11);p.keyboard.press('e');p.evaluate('Realm.test.render()');check('Exit returns to actual mine entrance',p.evaluate('Realm.diagnostics.scene')=='valley' and p.evaluate('Math.hypot(Realm.state.player.x,Realm.state.player.z+48)<.2'))
