  p.click('[data-action="adv-go"][data-id="spring"]');advance(30,True)
  if p.locator('#drawer').evaluate('(e)=>e.classList.contains("open")'):p.click('#close-panel')
  p.click('#interact');check('Relic opens story dialog',p.locator('#story-dialog').is_visible());check('Story pauses simulation',p.evaluate('Realm.diagnostics.adventure.paused'))
  check('Warning states the narrative stakes','Heaven is under attack' in p.evaluate('RealmAdventure.STORY.map(x=>x.body).join(" ")'))
