  p.locator('#story-buttons button').filter(has_text='Endurance').click();check('One gift persists and dialog closes',p.evaluate('Realm.state.adventure.reward')=='warden_stone' and not p.locator('#story-dialog').is_visible())
  check('Story restores preceding pause state',not p.evaluate('Realm.diagnostics.adventure.paused'))
