  p.evaluate('Realm.test.quality("balanced");Realm.test.setTime(17.5);Realm.test.view({overview:false,half:12});Realm.test.render()');p.wait_for_timeout(200);p.screenshot(path=str(OUT/'06-envoy-and-companion.png'),timeout=30000)
